const MAX_LIMIT = 100;
const DEFAULT_LIMIT = 20;

/**
 * Encode a row's sort-key values into an opaque base64 cursor.
 * The cursor must contain every column in the ORDER BY clause.
 */
function encodeCursor(row) {
    const payload = {
        // toISOString() preserves microsecond-free ms precision; if your
        // created_at has sub-ms precision, see the note below.
        created_at: row.created_at instanceof Date
            ? row.created_at.toISOString()
            : row.created_at,
        id: row.id,
    };
    return Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url');
}

/**
 * Decode an opaque cursor back into sort-key values.
 * Throws on anything malformed so the caller can return 400.
 */
function decodeCursor(cursor) {
    let payload;
    try {
        const json = Buffer.from(cursor, 'base64url').toString('utf8');
        payload = JSON.parse(json);
    } catch (err) {
        throw new InvalidCursorError('Cursor is not valid base64-encoded JSON');
    }

    if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
        throw new InvalidCursorError('Cursor payload must be an object');
    }

    const { created_at, id } = payload;

    if (typeof created_at !== 'string' || Number.isNaN(Date.parse(created_at))) {
        throw new InvalidCursorError('Cursor has an invalid created_at');
    }

    // Accept number or numeric string; normalize to string for pg.
    const idIsValid =
        (typeof id === 'number' && Number.isInteger(id)) ||
        (typeof id === 'string' && /^\d+$/.test(id));
    if (!idIsValid) {
        throw new InvalidCursorError('Cursor has an invalid id');
    }

    return { created_at, id: String(id) };
}

class InvalidCursorError extends Error {
    constructor(message) {
        super(message);
        this.name = 'InvalidCursorError';
    }
}

// GET /api/posts?limit=20&after=<cursor>
async function getPosts(req, res) {
    // --- limit: parse, clamp, reject garbage ---
    const rawLimit = req.query.limit;
    let limit = DEFAULT_LIMIT;
    if (rawLimit !== undefined) {
        const parsed = Number(rawLimit);
        if (!Number.isInteger(parsed) || parsed < 1) {
            return res.status(400).json({
                error: 'invalid_limit',
                message: '`limit` must be a positive integer',
            });
        }
        limit = Math.min(parsed, MAX_LIMIT);
    }

    // --- cursor: decode if present ---
    let cursor = null;
    if (req.query.after !== undefined && req.query.after !== '') {
        if (typeof req.query.after !== 'string') {
            return res.status(400).json({
                error: 'invalid_cursor',
                message: '`after` must be a single string value',
            });
        }
        try {
            cursor = decodeCursor(req.query.after);
        } catch (err) {
            if (err instanceof InvalidCursorError) {
                return res.status(400).json({
                    error: 'invalid_cursor',
                    message: err.message,
                });
            }
            throw err;
        }
    }

    // --- build the keyset query ---
    // Sort is (created_at DESC, id DESC), so "rows after the cursor" means
    // the row tuple sorts strictly LESS than the cursor tuple.
    // Postgres row-value comparison does exactly the right lexicographic thing.
    let sql;
    let params;

    if (cursor) {
        sql = `
            SELECT id, title, content, author_id, created_at
            FROM posts
            WHERE published = true
              AND (created_at, id) < ($1::timestamptz, $2::bigint)
            ORDER BY created_at DESC, id DESC
            LIMIT $3
        `;
        params = [cursor.created_at, cursor.id, limit + 1];
    } else {
        sql = `
            SELECT id, title, content, author_id, created_at
            FROM posts
            WHERE published = true
            ORDER BY created_at DESC, id DESC
            LIMIT $1
        `;
        params = [limit + 1];
    }

    const result = await db.query(sql, params);

    // --- N+1 trick ---
    const hasMore = result.rows.length > limit;
    const posts = hasMore ? result.rows.slice(0, limit) : result.rows;
    const nextCursor = hasMore ? encodeCursor(posts[posts.length - 1]) : null;

    res.json({
        posts,
        pagination: {
            hasMore,
            nextCursor,
            limit,
